INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Leitungssysteme in der IT immer verkabelt sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Leitungssystem für ein IT-Netzwerk plane?', 3, '[{"text": "Datenübertragungsrate", "correct": true, "because": "Entscheidend für Performance"}, {"text": "Farbcodierung", "correct": false, "because": "Sekundär"}, {"text": "Geringes Gewicht", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem IT-Leitungssystem?', 5, '[{"text": "Netzwerkkabel", "correct": true, "because": "Überträgt Daten"}, {"text": "Switches", "correct": true, "because": "Verteilt Signale"}, {"text": "Büromöbel", "correct": false, "because": "Kein technischer Faktor"}, {"text": "Monitore", "correct": false, "because": "Endgeräte, kein Leitungssystem"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leitungssysteme beeinflussen die Netzwerkleistung. b) Sie dienen nur der Energieversorgung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Datenübertragung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Leitungssystem für IT-Arbeitsplätze entwerfe?', 4, '[{"text": "Kabellänge", "correct": false, "because": "Beeinflusst Signal"}, {"text": "Übertragungsstandard", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Bürodeko", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Leitungssysteme nur für Datenübertragung genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Stromversorgung möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Leitungssystem in einem IT-Netzwerk?', 3, '[{"text": "Zuverlässige Datenübertragung", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität wichtiger"}, {"text": "Geringe Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Leitungssystem in der IT effektiv?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Fördert Datenfluss"}, {"text": "Geringe Störanfälligkeit", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Schwere Kabel", "correct": false, "because": "Nicht entscheidend"}, {"text": "Bunte Verkleidung", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Cat6-Kabel erhöhen die Übertragungsrate. b) Leitungssysteme sind immer drahtlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Drahtlos nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein IT-Leitungssystem?', 4, '[{"text": "Verkabelung", "correct": false, "because": "Kernkomponente"}, {"text": "Switches", "correct": false, "because": "Verteilt Daten"}, {"text": "Bürofarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Leitungssysteme in der IT immer physisch?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlose Systeme möglich"}, {"text": "Ja", "correct": false, "because": "Zu restriktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gut geplantes Leitungssystem?', 4, '[{"text": "Stabile Verbindungen", "correct": true, "because": "Sichert Datenfluss"}, {"text": "Geringe Latenz", "correct": true, "because": "Verbessert Performance"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Leitungssysteme nur für große Netzwerke wichtig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke brauchen sie"}, {"text": "Ja", "correct": false, "because": "Für alle relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Leitungssystem für ein IT-Büro zu optimieren?', 3, '[{"text": "Hochwertige Kabel", "correct": true, "because": "Fördert Übertragung"}, {"text": "Billige Router", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Kabel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leitungssysteme beeinflussen die Latenz. b) Sie sind immer wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem IT-Leitungssystem?', 5, '[{"text": "Kabelqualität", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Netzwerktopologie", "correct": true, "because": "Strukturiert Verbindungen"}, {"text": "Bürogröße", "correct": false, "because": "Sekundär"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Leitungssystem für IT plane?', 3, '[{"text": "Übertragungsgeschwindigkeit", "correct": false, "because": "Entscheidend für Netzwerk"}, {"text": "Störsicherheit", "correct": false, "because": "Sichert Zuverlässigkeit"}, {"text": "Dekoration", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Leitungssysteme immer verkabelt sein?', 3, '[{"text": "Nein", "correct": true, "because": "Drahtlos möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Leitungssysteme die Energieversorgung ausschließen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Strom übertragbar"}, {"text": "Ja", "correct": false, "because": "Zu eng gefasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein IT-Leitungssystem?', 4, '[{"text": "Übertragungsqualität", "correct": true, "because": "Sichert Performance"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]');
